interface PlaceOrderUseCase { // PORT DRIVING
    boolean placeOrder(String customer, double amount);
}

class PlaceOrderService implements PlaceOrderUseCase { // APLIKACJA - srodek heksagonu
    private final OrderRepositoryPort repository; // zalezy TYLKO od portu driven

    PlaceOrderService(OrderRepositoryPort repository) { this.repository = repository; }

    public boolean placeOrder(String customer, double amount) {
        repository.save(customer, amount);
        return true;
    }
}

interface OrderRepositoryPort { // PORT DRIVEN
    void save(String customer, double amount);
}

class InMemoryOrderRepositoryAdapter implements OrderRepositoryPort { // ADAPTER DRIVEN
    private final Map<String, Double> storage = new HashMap<>();
    public void save(String customer, double amount) { storage.put(customer, amount); }
}

class RestLikeAdapter { // ADAPTER DRIVING nr 1
    private final PlaceOrderUseCase useCase;
    RestLikeAdapter(PlaceOrderUseCase useCase) { this.useCase = useCase; }
    String handleRestLikeRequest(String customer, double amount) {
        return useCase.placeOrder(customer, amount) ? "201 Created" : "400 Bad Request";
    }
}

class CliLikeAdapter { // ADAPTER DRIVING nr 2 - TA SAMA aplikacja, inna "wtyczka"
    private final PlaceOrderUseCase useCase;
    CliLikeAdapter(PlaceOrderUseCase useCase) { this.useCase = useCase; }
    String handleCliLikeCommand(String customer, double amount) {
        return useCase.placeOrder(customer, amount) ? "Zamowienie zlozone" : "Blad";
    }
}

// ZLE: adapter (na zewnatrz heksagonu) sam zawiera regule biznesowa
class RestLikeAdapterFat {
    String handleRestLikeRequest(String customer, double amount) {
        if (amount <= 0) return "400 Bad Request"; // regula biznesowa W ADAPTERZE - zle miejsce
        // ... reszta logiki
        return "201 Created";
    }
}

// DOBRZE: regula biznesowa w aplikacji, adapter tylko tlumaczy format
class PlaceOrderServiceValidating implements PlaceOrderUseCase {
    private final OrderRepositoryPort repository;
    PlaceOrderServiceValidating(OrderRepositoryPort repository) { this.repository = repository; }

    public boolean placeOrder(String customer, double amount) {
        if (amount <= 0) return false; // regula TUTAJ - respektowana przez KAZDY adapter driving
        repository.save(customer, amount);
        return true;
    }
}
